        console.error('  - AZURE_KEY_VAULT_URL');
        console.error('  - AZURE_KEY_NAME (optional)');
        console.error('  - AZURE_CONTAINER_NAME (optional)');
      }
    }
    process.exit(1);
  }
}

main();
